-- ============================================================================
-- 045  Opravy otázek z testu portálu a doplnění pramene a okruhu
-- ============================================================================
--
-- CO CHYBĚLO
-- Test portálu (30. 9. 2026) našel v bance věcné chyby a aplikace bere otázky
-- z tabulky quiz_questions, ne z repozitáře — oprava jen v kódu by se
-- studentům neukázala.
-- • Otázka o „zastavovacím pásu (§ 17)“ tvrdila, že je to donucovací
--   prostředek. Výčet v § 17 odst. 2 zákona č. 555/1992 Sb. ho nemá.
--   Otázka se přepisuje na výčet donucovacích prostředků.
-- • Otázka „Jak přesně zní zákonná výzva…“ vydávala vymyšlenou větu za
--   doslovné znění. Zákon předepisuje jen slova „jménem zákona“.
-- • Vysvětlení k záznamu o použití DP odkazovalo na § 22; správně § 20.
-- • 361 otázek má prázdný pramen a 3 obecný „Banka otázek Supabase“, takže
--   u nich kartičky a banka neukazují číslo zákona. Doplní se z repozitáře.
--
-- CO TENHLE SKRIPT DĚLÁ
-- 1. Přepíše dvě chybné otázky (hledá je podle původního znění; kdo je
--    mezitím upravil, tomu se nepřepíšou).
-- 2. Opraví vysvětlení a pramen u záznamu o použití DP.
-- 3. Doplní pramen a okruh tam, kde chybí. Co lektor vyplnil sám, nemění.
--
-- Skript je idempotentní: druhé spuštění nic nezmění.
-- ============================================================================

BEGIN;

-- 1a. Zastavovací pás → výčet donucovacích prostředků (sp-20)
UPDATE public.quiz_questions
   SET question      = 'Který z uvedených prostředků NENÍ donucovacím prostředkem podle výčtu v § 17 odst. 2 zákona č. 555/1992 Sb.?',
       options       = to_jsonb(ARRAY['prostředek k zamezení prostorové orientace', 'zastavovací pás k zastavení prchajícího auta', 'pouta s poutacím opaskem a předváděcí řetízky', 'vytlačování štítem a vytlačování vozidlem']),
       correct_index = 1,
       explanation   = 'Výčet v § 17 odst. 2 písm. a) až p) je uzavřený a zastavovací pás v něm není. K zastavení vozidla lze z výčtu použít například vytlačování vozidlem (písm. o). Ostatní možnosti výčet obsahuje: pouta s poutacím opaskem (písm. e), předváděcí řetízky (písm. b), vytlačování štítem (písm. n) a prostředek k zamezení prostorové orientace (písm. p). (Právní úprava: § 17 odst. 2 zákona č. 555/1992 Sb.)',
       source        = '§ 17 odst. 2 zákona č. 555/1992 Sb.',
       topic         = 'Výčet donucovacích prostředků'
 WHERE question = 'Za jakých podmínek a jakým způsobem se smí použít donucovací prostředek zastavovací pás (§ 17)?'
   AND NOT EXISTS (SELECT 1 FROM public.quiz_questions WHERE question = 'Který z uvedených prostředků NENÍ donucovacím prostředkem podle výčtu v § 17 odst. 2 zákona č. 555/1992 Sb.?');

-- 1b. „Jménem zákona“ místo vymyšlené doslovné výzvy (va_10)
UPDATE public.quiz_questions
   SET question      = 'Jaká slova musí příslušník podle § 6 odst. 3 písm. b) zákona č. 555/1992 Sb. použít před výzvou k upuštění od protiprávního jednání?',
       options       = to_jsonb(ARRAY['„Jménem zákona“ – další znění výzvy zákon nepředepisuje, příslušník ji formuluje podle situace.', '„Jménem republiky“ – a za nimi celé znění výzvy, které pevně stanoví prováděcí vyhláška.', '„Z moci úřední“ – a za nimi celé znění výzvy, které pevně stanoví nařízení generálního ředitele.', 'Žádná – zákon určitá slova nevyžaduje, stačí srozumitelná výzva s pohrůžkou zákroku.']),
       correct_index = 0,
       explanation   = 'Podle § 6 odst. 3 písm. b) zákona č. 555/1992 Sb. použije příslušník před výzvou slova „jménem zákona“. Doslovné znění celé výzvy zákon nestanoví; příslušník ji formuluje srozumitelně podle situace a do záznamu o použití DP ji uvede tak, jak ji skutečně pronesl. (Právní úprava: § 6 odst. 3 písm. b) z. č. 555/1992 Sb.)',
       source        = '§ 6 odst. 3 písm. b) z. č. 555/1992 Sb.',
       topic         = 'Záznam o použití donucovacích prostředků'
 WHERE question = 'Jak přesně zní zákonná výzva příslušníka před použitím donucovacího prostředku dle § 6 odst. 3 písm. b) zákona č. 555/1992 Sb.?'
   AND NOT EXISTS (SELECT 1 FROM public.quiz_questions WHERE question = 'Jaká slova musí příslušník podle § 6 odst. 3 písm. b) zákona č. 555/1992 Sb. použít před výzvou k upuštění od protiprávního jednání?');

-- 2. Záznam o použití DP: § 20, ne § 22 (va_21)
UPDATE public.quiz_questions
   SET explanation = 'Zákon č. 555/1992 Sb. a navazující metodické listy jasně stanoví povinnost ohlásit a formálně zdokumentovat každé použití DP. Záznam musí obsahovat zákonné náležitosti (důvod, předchozí výzva, výsledek). (Právní úprava: § 20 odst. 1 a 2 zákona č. 555/1992 Sb. a Metodický list č. 5/2014)',
       source      = COALESCE(NULLIF(NULLIF(source, ''), 'Banka otázek Supabase'), '§ 20 odst. 1 zákona č. 555/1992 Sb. a Metodický list č. 5/2014')
 WHERE question = 'Kdo a do jaké lhůty zpracovává „Záznam o použití donucovacího prostředku“ po zákroku proti vězněné osobě?'
   AND explanation LIKE '%§ 22 zákona č. 555/1992 Sb.%';

-- 3. Pramen a okruh z repozitáře tam, kde chybí
UPDATE public.quiz_questions AS q
   SET source = CASE
                  WHEN q.source IS NULL OR btrim(q.source) = '' OR q.source = 'Banka otázek Supabase'
                  THEN COALESCE(v.source, q.source)
                  ELSE q.source
                END,
       topic  = CASE
                  WHEN q.topic IS NULL OR btrim(q.topic) = '' THEN COALESCE(v.topic, q.topic)
                  ELSE q.topic
                END
  FROM (VALUES
  ('Která ústavní práva a svobody jsou občanům ze zákona omezena při výkonu trestu odnětí svobody (VTOS)?', 'Ústavní právo a lidská práva', 'Listina základních práv a svobod (čl. 7, 8, 14, 26, 27) a zákon č. 169/1999 Sb., o VTOS'),
  ('Které vnitrostátní a mezinárodní instituce se zabývají ochranou lidských práv vězněných osob?', 'Ústavní právo a lidská práva', 'Zákon č. 349/1999 Sb., o Veřejném ochránci práv; Úmluva Rady Evropy o zabránění mučení (CPT)'),
  ('Které klíčové mezinárodní právní normy a standardy upravují zacházení s vězněnými osobami?', 'Mezinárodní standardy vězeňství', 'Pravidla Nelsona Mandely OSN (2015), Evropská vězeňská pravidla (2006/2020), Standardy CPT'),
  ('Jak definuje trestní zákoník trestný čin a jak se trestné činy dělí (§ 13 a § 14 TZ)?', 'Trestní právo hmotné', '§ 13 a § 14 zákona č. 40/2009 Sb., trestní zákoník'),
